WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('法学院', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '战略新疆域与海事法治建设', dept.dep_id, '本课程以国家海洋战略和全球海洋治理新形势为背景，围绕“战略新疆域”这一重要议题，系统探讨海事法治建设在深海空间拓展中的理论基础、制度结构与现实挑战。课程重点关注深海这一兼具战略性、公共性与高度不确定性的新疆域，分析其在资源开发、环境保护、科技利用与安全治理等方面对现有海事法律制度提出的深刻挑战。

课程将结合深海资源开发与环境保护的法治问题，重点讲授深海采矿、海洋生物资源利用、海洋生态风险防控以及国家管辖范围外区域（ABNJ）的法律规制，系统分析《联合国海洋法公约》框架下深海治理的基本规则及其最新发展，并引入国际海底管理局（ISA）、BBNJ协定等前沿制度实践。在此基础上，课程将探讨预防原则、人类共同继承财产原则、可持续发展原则等在深海法治中的具体适用，评估现行制度在应对深海不确定风险方面的能力与限度。

通过理论讲授与案例分析相结合的方式，本课程旨在引导学生理解深海作为战略新疆域的法治属性，把握国际海事法治的发展趋势，提升对深海环境风险、资源治理与规则建构问题的规范分析能力，为参与海洋强国建设和全球海洋治理提供法治视角与专业支撑。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

