WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('附属儿科医院', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '临床遗传学（下）', dept.dep_id, '临床遗传学是借助遗传学和基因组学信息，对遗传病进行基因诊断，治疗和临床医疗管理的一门学科。基因组医学时代，新的高通量测序技术的不断发展的今天，医学专业人员知识结构亟需更新。临床遗传学将包括基因组医学的新知识体系，提供从生殖医学，产前和孕期，新生儿，儿童和青少年以及成人整个生命周期涉及的多个学科的遗传病的发病过程，病因研究，临床诊断路径和相应的指南，临床治疗及管理，学会利用遗传学和基因组学的知识，解决临床的问题，提高我国整体医疗水平，推动精准医学等临床医学前沿研究领域的发展。本课程将组织多个有经验的临床一线的临床遗传专家授课。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
