WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('附属妇产科医院', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '妇科肿瘤临床要点及研究进展', dept.dep_id, '本课程内容以“常见肿瘤为核心、少见类型为补充、前沿进展为延伸、临床实践为支撑”展开，具体分为理论教学与临床实践两大模块：

（一）理论教学

按“总论-各论-交叉领域”逻辑划分，覆盖妇科肿瘤全谱系，结合“基础要点+研究进展”双维度讲解。总论章节介绍妇科恶性肿瘤研究进展概述，梳理领域发展脉络、核心诊疗技术演进、当前研究热点与挑战。各论包含宫颈癌专题，涵盖宫颈癌的研究进展、保育治疗、少见恶性肿瘤、复发宫颈癌的诊疗与预后管理。子宫肿瘤专题包括子宫内膜癌的研究进展、保育治疗、子宫肉瘤的病理分类、诊疗难点与进展。卵巢肿瘤专题覆盖卵巢上皮性恶性肿瘤、性索间质肿瘤、生殖细胞肿瘤、复发卵巢癌的治疗策略。其他妇科肿瘤专题介绍外阴癌与阴道癌、滋养细胞肿瘤、高危型妊娠相关滋养细胞肿瘤。此外还涉及妇科肿瘤的交叉与前沿领域包括介绍妇科肿瘤遗传学、子宫内膜异位症和子宫腺肌症恶变的相关内容。

（二）临床实践

以“多学科协作（MDT）”为核心形式，帮助学生衔接理论与临床。通过观摩妇科肿瘤MDT团队（妇科、病理科、影像科、肿瘤科等）对复杂病例（如晚期卵巢癌、复发宫颈癌）的诊疗讨论，学习病例汇报逻辑、多学科意见整合方法、临床决策制定过程；课后可结合示教病例回顾理论知识，深化理解。

教学周数16周，理论课32学时，见习4学时。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

