WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('附属妇产科医院', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '生殖医学概论', dept.dep_id, '通过在医学生（完成通识教育之后）中开设《生殖医学概论》课程，介绍生殖医学的基本知识，阐述疾病、社会和环境与生殖的关系及结局，以及生育相关问题，向医学生传播生殖健康的理念，加强医学生对生殖医学的认知，提高其对生命质量研究的兴趣，加强生殖医学在医学教学体系的重要性，提升医学生即未来医生对生殖医学的认知度，进而提升生殖医学在医学界乃至大众中普及度。本课程将继续为培养适应社会主义现代化建设和面向21世纪社会经济发展需要的“基础扎实、能力强、素质高”将来能从事生殖医学工作的高级实用型医学人才打下坚实的基础，为医学生今后从事生殖医学和其他临床学科的工作奠定理论基础和实践基础。加强生殖医学的人文医学教育和医德医风教育，弘扬医者精神的“真”“善”“美”，助力培养守初心、铸信念、强人文、有大爱的创新型卓越医学人才。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

