WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('附属华东医院', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '肥胖医学', dept.dep_id, '肥胖已成为严重威胁我国居民健康的重要危险因素，中国肥胖人数居全球第一，采取积极的应对措施对肥胖及所合并的代谢性疾病进行预防与治疗对于提高国人身体健康水平与生活质量具有重要的意义。虽然包括减重与代谢外科手术在内的肥胖医学在西方发达国家得到普遍开展和推广，但将其作为一个新兴学科引入我国并获得广泛推广应用仅十余年的时间，对其相关的基础理论与临床应用的认知度还存在不足。本课程旨在通过介绍肥胖的基本概念、发病机制与病理生理改变、诊断与评估方法、对机体各系统器官的危害以及治疗方法等在内的内容，使医学生对肥胖的基础理论与临床实践有正确的认识和理解，进而达到更好地促进肥胖医学在我国的发展，造福我国广大肥胖人群的目的。本课程紧密结合我国当前肥胖医学发展的现状，从病因、发病机制、病理生理改变、肥胖对机体心血管、呼吸、消化、内分泌等各系统器官的影响、其诊治现状，特别是减重代谢外科技术的应用等多学科领域系统阐述了当代肥胖医学所取得的成就与进展。通过本课程的学习，同学们将能够正确理解并掌握肥胖医学的相关知识，认识肥胖的危害，正确掌握包括减重与代谢外科手术在内的肥胖防治手段，进而有力促进肥胖防治知识的普及与临床应用，实现提高国人健康水平的目的。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

