WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('附属浦东医院', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '癌症：科学、人文与社会', dept.dep_id, '跨学科视角探讨癌症这一不仅关乎生命医学，更深刻影响社会、文化与伦理的问题。课程内容涵盖癌症的科学原理、流行趋势、历史沿革、社会影响、伦理困境以及在文学与大众媒体中的呈现。学生将通过剖析真实案例、研读科学文献、探讨人文叙事及参与跨文化讨论等，理解癌症如何受到社会因素的影响，并反映出社会对健康挑战的态度与应对方式。

作为一门复旦大学本科生通识核心课程，本课程适用于所有专业学生，不要求医学或理工背景。课程以英文授课，强调批判性思维、科学素养、人文关怀与全球视野的融合，旨在培养具备跨学科理解力、社会责任意识与道德判断能力的新时代公民。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

