WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('附属青浦区中心医院', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '外科微创学', dept.dep_id, '本课程总论部分详细介绍了微创外科观念的形成，以及现代微创外科的发展，微创外科技术如腹腔镜、胃肠镜、输尿管镜、胸腔镜、关节镜、介入等技术的特点及其应用，同时结合各专业的解剖特点，详细介绍了临床各专业普通外科、神经外科、泌尿外科、骨科、胸外科、血管介入微创外科、机器人外科、麻醉科等专业微创知识，通过微创学的历史、现状与演变，培养学生救死扶伤的医学人文理念和发展创新的科研理念，在我国微创外科的发展成果中培养自强自信、求实创新的精神；最后结合腹腔镜模拟实训室，掌握常用腹腔镜基本技能，加强学生的动手实践的能力。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

