  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '临床科学家培养理论与实践', dept.dep_id, '本课程围绕“临床科学家”的核心培养目标，系统讲授临床与基础研究结合的创新方法论，涵盖前沿科学技术应用、临床成果转化及伦理规范等关键环节,助于建立我国临床科学家培养体系。通过案例分析、跨学科研讨，帮助学生建立从临床问题出发的科研思维，掌握转化医学研究工具，提升解决复杂医学问题的能力。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

