WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('附属中山医院', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '多组学技术在临床医学中的应用', dept.dep_id, '本课程系统阐述生物质谱的仪器原理及其在临床疾病诊断与治疗中的前沿应用。课程首先系统讲解质谱核心技术，涵盖离子源、主流质量分析器（如四极杆、飞行时间、傅里叶变换离子回旋共振、静电轨道阱）的原理与串联质谱工作机制。在此基础上，课程重点介绍质谱在蛋白质组学、代谢组学及空间成像中的研究方法与应用实例，并进一步讲解如何整合多组学技术（如核糖体RNA测序、单细胞测序等），结合类器官芯片、生物可视化等交叉方法，系统解析真实世界中的复杂临床问题，从而揭示疾病分子机制，助力诊断标志物与特异性治疗靶点的发现。

课程亦关注质谱技术前沿进展，引入离子迁移谱-质谱联用（TIMS）、数据非依赖采集（DIA）及深度学习等新方法与分析策略，深入剖析单细胞质谱、宏蛋白质组学等在心血管疾病、肿瘤等重大疾病研究中的具体应用与转化潜力。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

