  VALUES ('高等教育研究所', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '课程论', dept.dep_id, '欢迎进入课程理论的学习旅程。课程从来不只是关于目标、编制、设计或评价，而是这些要素如何被筛选与塑造。这门课的核心，在于尝试系统性叩问课程之下那些看似无形却至关重要的根基：我们将一起探索，一门课程的背后究竟承载了何种关于知识与价值的哲学立场，反映了怎样的社会结构与权力关系，又建立在哪些关于教与学的心理学假设之上。理解这些理论，不是为了获得标准答案，而是为了获得使用能穿透纷繁课程现象、进行独立批判与创造的思维工具的能力。

因此，本课程将致力于创造一种深度参与、回归经典的学习体验。我们将以精读教育哲学、社会学与心理学的经典原著（比如杜威、泰勒、布鲁纳、弗莱雷等）为锚点，在密集而坦诚的课堂讨论中交锋观点，并通过分析真实课程案例、尝试微型课程设计等实践，让抽象理论在具体情境中显形。最终，我们将运用这种理论洞察力，共同探讨本土的课程改革实践。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

WITH dept AS (
  SELECT dep_id FROM Department WHERE dep_name = '高等教育研究所'
), course_row AS (
  SELECT c.course_id
  FROM Course c
  JOIN dept d ON d.dep_id = c.dep_id
  WHERE c.course_name = '课程论'
), existing_teacher AS (
  SELECT t.people_id
  FROM Teacher t
  JOIN People p ON p.people_id = t.people_id
  JOIN dept d ON d.dep_id = t.dept_id
  WHERE p.name = '王欣欣'
  ORDER BY t.people_id
  LIMIT 1
), inserted_person AS (
  INSERT INTO People (name, gender, phone, email)
  SELECT '王欣欣', 'O', NULL, NULL
  WHERE NOT EXISTS (SELECT 1 FROM existing_teacher)
  RETURNING people_id
), person_row AS (
  SELECT people_id FROM existing_teacher
  UNION ALL
  SELECT people_id FROM inserted_person
  LIMIT 1
), teacher_row AS (
  INSERT INTO Teacher (people_id, staff_no, title, dept_id)
  SELECT person_row.people_id,
         'CR82DFC5DB46',
         '其他',
         dept.dep_id
  FROM person_row, dept
  ON CONFLICT (people_id)
  DO UPDATE SET dept_id = EXCLUDED.dept_id
  RETURNING people_id
)
INSERT INTO Teaching (teacher_id, course_id, semester)
SELECT teacher_row.people_id, course_row.course_id, '2025-2026-2'
FROM teacher_row, course_row
ON CONFLICT (teacher_id, course_id, semester) DO NOTHING;

