WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('高等教育研究所', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '课程与教学论', dept.dep_id, '《课程教学论》课程面向以中学学科教学（初中/高中历史或物理等）为职业指向的研究生，系统介绍课程与教学的核心概念、理论谱系与分析框架，并聚焦我国基础教育课程改革语境（课程方案、课程标准、教材与考试评价改革等），培养学生以理论解释与改进实践的能力。

本课程（A课程）与联修课程《课程设计与教学创新实践》（B课程）共同构成“理论—设计—试讲—反馈”的学习闭环：A课提供理论工具、政策与文献分析框架、课程实施与评价的解释模型；B课要求学生完成一节课教案与微课试讲并迭代。A课的重要任务是引导学生将B课产生的设计、试讲与反馈证据上升为 理论支撑的分析与反思 。在此，建议学生将A课与B课同学期修读，不得单独修读。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

