WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('高分子科学系', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '聚合物膜化学与膜分离', dept.dep_id, '《聚合物膜化学与膜分离》课程系统讲授膜分离技术的基本原理、膜的制备与表征方法、膜分离过程及其实际应用等。课程内容分为两大模块：

1. 膜化学模块 ：重点介绍膜材料的分类、选择及其改性，多孔膜与致密膜的制备方法、膜的结构及其调控方法、以及常见分离膜的表征技术等。

2. 膜分离模块： 主要讲授膜分离过程的基本原理、技术特点以及操作模式，包括反渗透、纳滤、超滤、微滤、电渗析等典型膜技术的工作原理，分析各种膜分离组件的结构和特点，同时讲授这些膜过程的工业应用及研究进展，并列举丰富的工程应用实例。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
