WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('公共卫生学院', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '环境与儿童健康', dept.dep_id, '儿童作为特殊的群体，对环境有害因素具有天然的高敏感性和脆弱性。环境与儿童健康是一门聚焦环境因素与儿童生长发育及健康状况关联性的交叉学科，融合了环境科学、儿科学、流行病学、毒理学、公共卫生等多个领域的理论与方法。其核心目标是揭示各类环境因素对儿童健康的影响规律，识别关键风险点，为制定针对性的预防控制策略、保障儿童健康成长提供科学依据。环境与儿童健康的内容主要包括三大板块：一是识别关键环境风险因素，二是探索暴露评价与致病机制，三是制定与实施预防控制策略。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
