  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '流行病学偏倚分析技术', dept.dep_id, '偏倚的产生有其固有的原因。本课程以系统介绍偏倚的理论和方法为目标，基于因果思维结合因果图，首先介绍因果图的语言、规则及应用，接着从因果图阐释偏倚的结构分类，重点介绍三对六类偏倚（测量偏倚和思维偏倚、选择偏倚和混杂偏倚、因果路径偏倚和效应修饰偏倚）发生的原因及其对效应估计的影响，中介分析及其偏倚控制，通过实例介绍定量分析偏倚的基本分析思路及其SAS软件实现方法，最后以作业展示形式进行班级内交流。（选课参考微信阅读号：CausalEpi; 或链接 https://mp.weixin.qq.com/s/KQIZhTf2_u1uil0Q4c280g)'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

