WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('古籍整理研究所(中国古代文学研究中心)', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '专书研究', dept.dep_id, '《专书研究》是本研究所为硕士研究生开设的特色专题课程，每年聚焦一门经典著作或一个专门学术领域进行深度研读与探讨。本年度课程主题为“悉昙学文献研究”。

悉昙学是研究古印度梵文字母体系（悉昙文字）及其在东亚传播、演变与应用的传统学问，是沟通语言学、文献学、宗教学与文化交流史的重要桥梁。本课程将以汉语历史音韵学中的梵汉对音研究为核心视角，系统梳理悉昙学在东亚文化圈，特别是在中国与日本的发展脉络。课程内容主要分为三个部分：一是悉昙学发展史，探究其自印度经中亚至中国、再传入日本的传播路径与历史语境；二是阐释悉昙学的核心概念与知识体系，如“十六音”（元音系统）、“三十三字”（辅音系统）的根本原理与结构，并深入解析《悉昙藏》等集成性著作的编撰思想与学术价值；三是精选若干部标志性文献进行文本精读与对音分析，包括唐代智广的《悉昙字记》（悉昙入门基础文献）、宋代惟净等编著的《景佑天竺字源》（宋代官方梵字研究代表作）、日本安然所著的《悉昙藏》（集大成的悉昙学百科全书），以及日僧信范的《悉昙三秘抄》（包含秘传知识的晚期著作）等。通过细读文本，结合敦煌写本、日本古抄本等材料，学生将学习如何运用对音方法，分析梵汉语音对应规律，并理解悉昙文献在佛教密教传承、汉字音韵史研究以及中日文化交流中的关键作用。

本课程旨在培养学生处理古代多语种、跨文化文献的学术能力，掌握历史语言学中的对音研究方法，并深化对东亚知识史与文化交流复杂性的理解。要求学生具备一定的古汉语阅读能力和语言学基础，鼓励来自语言学、文献学、历史学、宗教学等不同专业背景的学生选修。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

