WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('国际关系与公共事务学院', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '区域国别研究Ⅱ', dept.dep_id, '本课程是复旦大学国际关系与公共事务学院国际事务专业硕士学位专业课，与“区域国别研究I”一起构成国际事务型硕士课程区域研究教学的主要内容。

近年来，全球气候变化和国际地缘政治冲突等具有全球影响的事件，不断推动全球南方国家的整体觉醒，全球南方逐渐走向国际政治舞台的中心。与一些专注于社会文化和国情概况介绍的课程不同，本课程注重从区域国别研究的视角出发，通过课堂讲授和开放探讨等形式，尝试理解全球南方及其主要国家具备怎样的共性与特性的国情，以及这些共性和特性如何影响这些国家在国际事务主要议题中的政策选择。

本课程授课教师全部有着长期研究全球南方主要区域和国家的田野调查和教学科研经历。本课程设置了南亚、东南亚、中东、拉美和非洲等五个模块，各个模块相对独立，又交叉为一体，聚焦重点区域和国家的政治、经济和外交议题，并贯穿相关区域国别研究理论与方法，从而构建一个全方位理解全球南方国家的知识框架。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

