WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('国际关系与公共事务学院', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '算法治理', dept.dep_id, '本课程以 算法治理（Algorithmic Governance）与智能治理（AI-enabled Governance）为核心分析框架，系统解读以大模型、算法决策系统、平台化治理和算力基础设施为代表的新一轮数字与智能技术革命，如何重塑国家能力、公共权力运行方式、社会结构、经济组织形态与规范秩序 ，并深入探讨算法嵌入治理过程所引发的 权力再分配、制度张力与治理范式转型 问题。

课程紧密结合 全球最前沿的真实案例与政策实验 ，涵盖算法执法、智能城市、平台监管、自动化决策、生成式AI公共应用等关键议题，通过 跨国比较与制度分析 ，对数字化转型中的“技术乐观主义”与“技术恐慌论”进行冷静反思，帮助学生在理解算法与模型基本原理的基础上，系统识别其 治理潜能、结构性风险与长期制度后果 。

在理论与实践互动中，课程将对比分析 欧美算法治理与AI监管趋势 （如风险分级治理、算法问责、可解释性制度、算力与数据主权）与 中国在数字治理与智能治理中的独特实践路径 ，探讨不同政治制度和治理传统下算法嵌入公共治理的差异化逻辑，推动对“ 算法向善 ”“ 负责任AI ”与“ 数字善治 ”的系统性理解与本土化理论建构。

课程采用高度互动与可视化的教学方式，配备 前沿、审美与信息密度并重的高质量教学PPT ，融合政策文本、数据可视化、真实系统界面与情景化讨论，力求做到 好看、好玩、有料 ，同时引导学生形成 面向未来治理挑战的批判性思维与战略性判断能力 。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

