  SELECT '学术伦理与规范', dept.dep_id, '本课授课教师主体为学院院长、书记、学术委员会主任、教指委主任、系主任、分管教学科研副院长、 教授代表、青年教师代表，课程面向全体研究生，内容围绕学院院风学风之风气弘扬、学人学术之学脉传承、个人大学国家之理想使命，目的是将学院院风和治学传统施教于本院研究生，帮助学生树立卓越为公的学术情怀。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
