ON CONFLICT (teacher_id, course_id, semester) DO NOTHING;

WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('核科学与技术系', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
