), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '中微子与暗物质实验前沿', dept.dep_id, '中微子和暗物质是当代物理和宇宙学天空的两片乌云，是当前国际粒子物理与核物理研究的前沿与热点。本课程主要围绕中微子和暗物质两大主题，内容涵盖中微子探测、暗物质搜索的基本原理、实验方法及最新研究进展。在系统讲授基础知识的同时安排专题介绍，紧跟当前国际研究前沿，探讨稀有物理过程探索，引导和培养学生的创新思维能力。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

