WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('护理学院', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '护理领域量性研究的分析方法', dept.dep_id, '《护理领域量性研究的分析方法》是一门面向护理学硕士、博士研究生的研究生专业选修课，3 学分、共 54 学时，春季学期开设。课程聚焦护理研究中常见的问卷/量表与二次数据分析场景，系统训练从数据预处理到统计建模、再到结果解释与科研写作的完整分析链条，强调“可复现的分析思路 + 可落地的工具实操”。

课程目标包括：理解量性研究中数据预处理、统计描述与推断的关键逻辑；掌握回归、分类与降维、面板数据分析与预测模型等常用方法；并能结合护理研究中常见的潜变量、混杂因素与连续变量等数据特征，独立选择合适的数据来源与统计策略开展分析实践。建议修读者已完成《医学统计学》《护理研究》和/或《循证护理学》等课程。

课程内容覆盖：量表心理测量学指标分析、样本量计算与 PASS 应用、数据录入与清洗；回归/广义线性回归与多变量回归（混杂控制）；路径分析与结构方程模型；聚类/判别、探索性与验证性因子分析；潜在类别/潜在剖面模型；面板数据因果推断、重复测量分析、静态/动态面板与 GMM；以及临床预测模型、复杂网络分析、孟德尔随机化等专题，帮助学生形成“选题—数据—方法—解释—写作”的闭环能力。

教学采用理论讲授 + 案例解析 + 课堂工具实训 + 小组汇报的混合模式。考核由课堂出勤（20%）、小组讨论与汇报（30%）、课程论文及汇报（50%）构成，强调以指定或公开数据完成可解释、可复现的完整分析报告。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

