WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('护理学院', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '健康教育学', dept.dep_id, '健康教育学是一门研究传播保健知识和技术，影响个体和群体行为，消除有害因素，预防疾病，促进健康的科学。它通过传播和教育手段，向社会、家庭和个人传授卫生保健知识，提高自我保健能力，养成健康行为，纠正不良习惯，消除危险因素，防止疾病发生，促进人类健康和提高生活质量。健康教育学作为教育的重要内容，已经成为世界上许多发达国家和地区学校教育的基本任务，成为素质教育的重要标志。
健康教育学是护理学与公共卫生学相结合的交叉学科，旨在促进和维护社区人群的健康。随着社会经济的发展，疾病谱和死亡谱逐渐从传统的传染性疾病转向慢性非传染性疾病，居民对健康的要求也不再仅限于无病状态，而是追求持续的健康管理、护理照顾和健康指导。因此，传统的专科医疗护理已无法满足人们日益多样化的健康需求。健康教育学的出现顺应了时代的变化，是21世纪健康管理领域的重要发展方向之一。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

