WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('护理学院', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '社区护理', dept.dep_id, '社区护理学是护理学和公共卫生学相结合的新兴学科，用以促进和维护社区人群健康的综合学科。随着社会经济的发展，人们的疾病谱和死亡谱已由原来的传染性疾病逐渐转变为慢性非传染性疾病，人们对健康的要求也不仅仅满足于没有疾病，而是要求得到持续性的医疗护理照顾和保健指导，因此，单纯的专科医疗护理已远远不能适应广大居民的健康需要。社区护理学的产生顺应了时代发展的要求，是21世纪护理发展的重要方向之一。
社区护理以健康为中心，社区人群为服务对象，促进和维护社区内个人、家庭及人群的健康为主要目标。本课程结合国内外社区护理的发展现状，以社区中的个人、家庭和社区健康为主线，介绍社区护理的基本理论和工作方法；社区健康护理；家庭健康护理；社区重点服务人群包括儿童和青少年、妇女、亚健康人和中年人、老年人、慢性病病人、残疾人和精神障碍者等的保健与护理。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

