WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('华山临床医学院', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '常见疾病与健康促进', dept.dep_id, '课程通过四个部分开展：

第一部分 理论学习：医学社会实践的传承与价值（4学时）。学生了解医学社会实践的医学传承，系统性学习科普课件制作和科普宣讲的方法与技巧；

第二部分 临床思训：临床学习体验与科普实践培训（10学时）。学生跟随临床导师体验临床诊疗过程，学习一种常见疾病诊疗知识，结合最新的临床指南和专家共识，制作科普宣讲课件和科普试讲；

第三部分 实践提高：宣讲实践服务老区与参观红色教育基地（38学时）。师生集体赴安徽六安，体验基层医疗状况，以医学科普和医疗咨询服务老区群众；

第四部分 交流感悟：以学生所学反馈学校与社会（2学时）。分组讨论总结实践收获，撰写实践报告，制作科普短视频反哺学校与社会。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

