WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('华山临床医学院', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '精神医学', dept.dep_id, '绪论： 精神医学的概念，精神医学的发展概况，精神医学与相关学科，精神医学的临床前沿问题，怎样学好精神医学。 病因学： 精神障碍的生物学因素包括：遗传因素、神经递质、神经内分泌、脑结构及脑功能改变等，环境因素包括：移民、城市化、童年创伤、物质使用等。病因学研究面临的挑战。精神障碍的诊断和分类系统。 精神症状学： 包括感知障碍，思维障碍，情感障碍，意志障碍，注意障碍，动作行为障碍，记忆障碍，智能障碍，意识障碍，自我意识障碍；常见的精神科综合征；接触精神障碍患者面谈的基本原则与技能。精神障碍诊断方法。 双相障碍和抑郁障碍： 包括双相障碍和抑郁障碍的概述、流行病学、病因和发病机制、临床表现与类别、诊断和鉴别诊断、治疗与预防。 精神分裂症： 包括概述、流行病学、病因和发病机制、临床表现与类别、诊断和鉴别诊断、治疗与预防。 脑和躯体疾病所致精神障碍： 阿尔茨海默病和血管性痴呆概述、流行病学、病因和发病机制、临床表现与类别、诊断和鉴别诊断、治疗与预防。其他脑部疾病和躯体疾病所致精神障碍概述。 焦虑障碍： 包括焦虑障碍概述，惊恐障碍、广泛性焦虑障碍、社交焦虑障碍的流行病学、病因和发病机制、临床表现与类别、诊断和鉴别诊断、治疗与预防。 强迫症和创伤与应激相关障碍： 包括概述、流行病学、病因和发病机制、临床表现与类别、诊断和鉴别诊断、治疗与预防。 孤独症、ADHD和精神发育迟滞： 包括孤独症、ADHD和精神发育迟滞的概述、流行病学、病因和发病机制、临床表现与类别、诊断和鉴别诊断、治疗与预防。 人格障碍与性心理障碍 ，包括人格障碍、性心理障碍的病因、临床表现、分型、诊断和鉴别诊断、治疗与预防。 精神障碍治疗， 包括心理治疗、药物治疗、物理治疗、康复治疗四个部分，以及抗精神病药物、抗焦虑药无、抗抑郁药物、心境稳定剂、益智药物等临床应用。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

