  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '皮肤病学B', dept.dep_id, '介绍皮肤科的基本理论，包括皮肤的解剖和功能、皮肤病的症状和治疗。结合总论分别讲授皮肤性病的常见病和多发病的诊断、鉴别诊断和防治原则，包括感染性皮肤病、变态反应性皮肤病、药疹、神经功能障碍性皮肤病、职业性皮肤病、红斑鳞屑性皮肤病、结缔组织病等。通过课程认识皮肤科常见疾病。同时通过课程的学习，使学生了解上医及附属医院皮肤科学界老前辈的光辉事迹和艰难历程，从而结合课程思政，向广大学生传达正确的科学知识的同时，进一步传达积极向上的思想。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

