  SELECT '外科学（下）', dept.dep_id, '外科学具体内容包括：骨科常见疾病（运动系统检查、骨折、关节感染、手外伤等）；泌尿外科常见疾病（泌尿系统损伤、感染、泌尿系结石及生殖系统肿瘤等）；胸外科常见疾病（胸部外伤、肺癌、食管癌等），以及外科基本操作。外科学的教学过程包括课堂教学和临床示教。授课内容以常见病、多发病为重点，同时介绍国内外医学领域的一些新进展，以帮助了解现代医学的发展新趋势。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
