  SELECT '外科学B(上)', dept.dep_id, '课程内容包括：外科常见病、外科与手术。手术是基于无菌操作、休克、感染、营养以及多器官衰竭等基本理论和技能。介绍了外科疾病的病因、病理、临床表现、诊断与鉴别诊断、防治原则及手术指征等。操作是培养具有严格无菌观念和基本操作训练的学生。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

