  INSERT INTO Course (course_name, dep_id, description)
  SELECT '中医学', dept.dep_id, '中医药学具有完整的理论体系，内容非常丰富。本课程详细介绍中医药学的基本理论如阴阳五行、脏腑理论、气血津液理论、药性理论，而且具体介绍临证诊治方法如四诊八纲、辨证论治、治则治法，及中医各科如何分型论治。在教学过程中注重职业素养培养、文化认同提升及科学精神探讨。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
