WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('环境科学与工程系', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '环境灾害与启示', dept.dep_id, '课程以经典环境灾害事件为依托，以当前重大环境问题为引领，围绕区域性灰霾、全球气候变化、水体富营养化、土壤重金属污染到土壤沙漠化等主题，向学生介绍环境风险、环境问题向环境灾害的演变过程，再现石化燃料利用、工业文明和现代科学技术在环境灾害事件的印记和角色。使学生掌握环境科学的基本概念、环境灾害的重大社会影响和灾害发生的机制机理以及环境污染防治的应对策略。引导学生运用辩证唯物主义世界观分析各种环境灾害形成的特定历史原因及其危害，帮助同学理解科学是一把双刃剑，领悟人与自然和谐统一、相互依存的自然发展规律.'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

