  VALUES ('环境科学与工程系', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '土壤环境化学', dept.dep_id, '水体及界面化学过程在微量金属和营养元素的生物地球化学循环，以及污染物在土壤和地下水等环境中的迁移与归趋中发挥着重要作用。本课程围绕自然与工程水环境体系中相关的化学反应过程展开讲授。课程内容主要聚焦于土壤与地下环境体系中的化学过程，同时也将系统介绍水化学无机部分的一般概念与研究方法。课程强调定量分析方法，重点训练学生利用化学平衡与动力学理论解决实际环境化学问题的能力，并对土壤介质中重要的环境化学行为进行讲解。课程主要内容包括：化学平衡与反应动力学、酸碱平衡与碱度、土壤矿物的溶解与沉淀过程、氧化还原反应、微团聚体（microaggregates）概念、碳循环、磷循环、有机污染物的环境归趋与迁移，以及土壤生态系统相关过程。课程在讲授土壤化学基本原理的同时，将结合典型案例研究，对相关过程进行深入分析。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
