  SELECT '代谢分子医学与疾病(H)', dept.dep_id, '课程分为①脂质代谢与其相关性疾病；②糖代谢与其相关性疾病；③核酸代谢与其相关性疾病；④氨基酸代谢与其相关疾病； ⑤肿瘤代谢特点，共五篇内容。这门课程填补了我们国家有关代谢的途径及其与疾病关系的空白，并加入肿瘤代谢的最新研究进展。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

