WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('基础医学院', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '高级医学微生物学', dept.dep_id, '医学微生物学是临床医学、基础医学、法医学专业必修的基础课程，主要包括五个方面的内容：基础细菌学，临床细菌学，基础病毒学，临床病毒学和病原性真菌。基础细菌学和病毒学主要论述细菌和病毒的形态结构、生长繁殖、遗传变异、致病与免疫、实验室诊断和特异性防治等；临床细菌学和病毒学着重描述与医学相关病原菌和病毒的生物学性状，致病性与免疫反应、微生物学检查和防治；病原性真菌主要论述真菌的主要特点及其与医学的关系。

在授课过程中，将微生物学前沿研究热点引入课程讲授，使学生能及时掌握新理论和新技术，熟悉常见微生物的分子生物学知识及防治对策，跟踪前沿技术理论及研究进展，为今后的研究工作打下必要的理论和实验基础。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

