  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '局部解剖学', dept.dep_id, '“局部解剖学”是解剖学的重要组成部分，是连接系统解剖学与临床医学、影像学及外科学等学科的 核心桥梁课程 。它建立在系统解剖学（按器官系统学习）的知识基础上，转变为以 人体的特定区域（颈部、胸部、腹部、四肢） 为学习单位，重点研究： 各区域内 器官与结构的位置、形态、毗邻关系； 层次结构 （由浅入深：皮肤、浅筋膜、深筋膜、肌层、血管神经鞘、骨骼及体腔等）； 器官的血液供应、淋巴回流和神经支配； 重要的解剖学标志、三角、间隙、通路 及其临床意义。本课程重点培养和锻炼学生的解剖操作实践技能和理论联系实际的能力。 它不仅要求学生记忆知识，更要求其具备将知识转化为解决临床实际问题的能力，是医学生成长为合格医师的关键一步。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

