WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('基础医学院', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '神经解剖学', dept.dep_id, '《神经解剖学》是人体解剖学的重要组成部分，也是神经科学的基础，是研究人神经系统形态与结构的科学。自19世纪中叶神经元学说建立起，随着科学发展对神经系统结构深入探索的需要，以及新的研究方法和技术手段的发明和进步，都极大地促进了《神经解剖学》领域的扩展。神经通路追踪法的问世和发展，使脑内各结构间的相互联系以及神经回路的知识越来越丰富。免疫组织化学方法的应用，又把神经元的形态与神经递质的分析结合了起来，从而得以阐明其功能，并为探索神经系统疾患的机制以及药物治疗的研究开辟了新的道路。扎根形态学知识，与功能相结合，密切联系临床，这些特征使《神经解剖学》的发展呈现出无限的生命力。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

