WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('基础医学院', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '生殖医学与生殖生物学', dept.dep_id, '生殖生物学是研究整个生殖过程的一门学科。它既是发育生物学的一个分支，也是生理学的一个分支，是融合现代生物化学、细胞生物学、内分泌学和分子生物学等学科的交叉学科。生殖医学是一门综合性的新兴学科，涉及生育、不育、节育和出生缺陷等，主要任务是通过常规的诊断和治疗措施，将现在的各种生殖技术应用于不育病人，使其产生后代。本课程通过围绕生殖细胞发育成熟、受精以及胚胎发育等重要生物学事件，结合临床常见的生育问题，如1）不孕不育；2）生殖肿瘤；3）出生缺陷，开展相关发病机制的探讨，了解如何在治疗肿瘤的同时，保存其生育力，以及出生缺陷的早期筛查与预防机制等。开展以基础理论与临床病例相结合的自主学习方式，将有助于提高研究生的理论水平，为基础研究与临床实践打好基础。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

