  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '现代组织化学（一）', dept.dep_id, '随着生物科学研究技术的发展、在组织切片或者细胞涂片上引入生物化学的酶-底物反应、免疫化学的抗原-抗体反应及分子生物学的DNA或RNA基因片段杂交反应，与组织形态学技术相结合分别形成酶组织化学、免疫组织化学和杂交组织化学，统称为现代组织化学。通过光学或电镜观察，人们能够在组织、细胞及核酸水平进行定性、定位和定量观察，使细胞形态与功能有机结合，在当今精准医学的时代背景下，现代组织化学技术已经成为生命科学和医学研究以及临床病理诊断中必须的重要技术手段。
在这门课程中我们将介绍常见的组织化学技术原理及实验过程中的基本注意事项，实验课将安排学生进行实验操作或录像演示实验步骤，并介绍最新的技术进展。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
