), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '药理学', dept.dep_id, '包括药物效应动力学（药效学）及药物代谢动力学（药代学）。药效学主要研究药物对机体（包括病原体）的作用及作用机制，以阐明药物治疗疾病的规律，对指导临床合理用药和减少毒副作用提供理论依据；药代学主要研究药物的体内过程（包括吸收、分布、代谢及排泄），阐释药物在体内的动态规律，从而确定给药剂量及间隔时间等。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

