WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('基础医学院', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '医学分子生物学', dept.dep_id, '二十一世纪是“生命科学世纪”，医学分子生物学是分子生物学的一个重要分支，是从分子水平研究人体在正常和疾病状态下生命活动及其规律的一门科学。医学分子生物学主要解决两方面问题：一是阐明疾病和亚健康状态发生和发展的分子机制；二是在前一问题理论的基础上，发展新型技术，为疾病的诊断、治疗、预防提供崭新的、可行的手段。作为一门课程，医学分子生物学涵盖了医学各专业学生必须学习的分子生物学基本知识，以及分子生物学在医学领域中形成的专门研究领域及相关知识。这些基础知识将为医学各学科专业知识的学习，为将来了解各学科领域的研究进展奠定坚实的基础。

本课程医学分子生物学自2002年开课以来，一直是全校基础与临床专业的博士研究生必修课。本门课程总课时数为（52）课时，本门课程共计（3）学分。 迄今为止，修读本门课程累计研究生数共（960）人。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

