WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('基础医学院', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '医学微生物学前沿', dept.dep_id, '《医学微生物学前沿》是一门面向研究生/高年级本科生开设的前沿性、研究导向型课程，旨在系统介绍 现代细菌学领域的核心理论、前沿进展及关键研究技术 ，帮助学生在扎实掌握基础知识的同时，深入理解当前学科发展的重要科学问题和研究思路。

课程内容围绕六个相互关联的专题展开，包括：

1） 科研基金申请书的撰写与研究设计 ， 2） 细菌生理与代谢调控机制 ， 3） 细菌基因表达的分子调控 ， 4） 细菌信号转导及调控网络 ， 5） 细菌抗生素耐药与持留机制 ， 6） 细菌基因组进化与环境适应 。

在理论教学的基础上，课程系统引入 Nature 、 Science 、 Cell 等国际顶级学术期刊的最新研究成果，通过文献研读与讨论，引导学生理解前沿技术方法、研究范式及尚未解决的关键科学问题。

本课程强调 科研思维训练与问题导向学习 ，旨在为从事细菌感染相关基础研究、疾病防治及转化研究奠定坚实基础，拓展研究生的学术视野，培养具备独立科研能力和创新潜力的高层次科研人才。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

WITH dept AS (
  SELECT dep_id FROM Department WHERE dep_name = '基础医学院'
), course_row AS (
  SELECT c.course_id
  FROM Course c
  JOIN dept d ON d.dep_id = c.dep_id
  WHERE c.course_name = '医学微生物学前沿'
), existing_teacher AS (
  SELECT t.people_id
  FROM Teacher t
  JOIN People p ON p.people_id = t.people_id
  JOIN dept d ON d.dep_id = t.dept_id
  WHERE p.name = '高谦'
  ORDER BY t.people_id
  LIMIT 1
), inserted_person AS (
  INSERT INTO People (name, gender, phone, email)
  SELECT '高谦', 'O', NULL, NULL
  WHERE NOT EXISTS (SELECT 1 FROM existing_teacher)
  RETURNING people_id
), person_row AS (
  SELECT people_id FROM existing_teacher
  UNION ALL
  SELECT people_id FROM inserted_person
  LIMIT 1
), teacher_row AS (
  INSERT INTO Teacher (people_id, staff_no, title, dept_id)
  SELECT person_row.people_id,
         'CR54A95867DA',
         '其他',
         dept.dep_id
  FROM person_row, dept
  ON CONFLICT (people_id)
  DO UPDATE SET dept_id = EXCLUDED.dept_id
  RETURNING people_id
)
