WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('经济学院', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '企业价值与无形资产评估', dept.dep_id, '本课程系统讲授企业价值评估与无形资产评估的理论方法与实务应用，重点围绕收益法框架下的企业价值评估展开，结合实际案例深入分析现金流估值模型（DCF）的基本原理、估值流程及关键参数的获取与处理。课程内容涵盖企业财务报表重整、经营绩效预测与分析、折现率与终值设定、估值结果检验等核心问题，并在此基础上引入实物期权评估方法，分析不确定性与管理灵活性对企业价值和投资决策的影响。

本课程坚持理论与实务并重的教学原则，在系统讲解企业价值评估与无形资产评估理论的同时，结合典型案例开展分析与讨论，强化定性分析与定量分析的结合。通过对专利、商标、著作权、数据资产、客户关系等无形资产的评估方法进行系统讲解，引导学生准确识别无形资产特征，理解其价值形成机制，掌握企业价值评估与无形资产评估的主要方法与技术路径，提升运用经济学分析工具和定量分析工具解决实际评估问题的能力。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

