WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('经济学院', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '数量分析方法', dept.dep_id, '本课程是金融类（金融、资产评估等）专业基础课程之一，旨在为学生的经济逻辑推断、资产评估和定价行为提供科学的量化手段，也是学生撰写学位论文和科学论文、进一步深造等不可或缺的方法基础。本课程主要分为以下三个部分：
第一部分（1-9周），横截面数据的回归分析。此部分是计量经济学的基础部分，利用最简单的统计方法并针对最简单的数据得出推断结论，是进一步深入学习计量经济学的必备知识。内容包括主要的计量经济学假设、系数的估计和推断，模型的结构设定等。
第二部分（10-12周），时间序列数据的回归分析。相对于前一部分，这里针对的是具有纵向或动态特征的数据，如股票和资产价格、利率和GDP增速等。这类数据具有显著的序列相关和异方差性等特征。我们将详细讲解如何处理这些问题，以得到可靠、精确的统计推断。
第三部分（13-16周），高级专题研讨。本部分主要介绍三个问题：其一，如何减少内生性问题造成的虚假回归问题。这一问题被称为计量经济学的“原罪”。其二如何分析跨时横截面数据。其三，如何分析短面板数据。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

