WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('口腔医学院', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '口腔设备学', dept.dep_id, '人工智能是计算机科学最有发展潜力的分支之一,也是涉及数学、信息论、语言学、心理学等学科的交叉学科。随着人工智能的飞速发展及其在医疗领域的广泛应用,特别是与大数据在医学实践中的日益融合,对培养21世纪的医学人才提出了新的要求。
新医科是在人工智能、大数据为代表的新一轮科技革命和产业变革基础上应运而生，涵盖生命全周期、健康全过程，通过医工理文融通，涌现出精准医学、转化医学、智能医学等医学新专业”。
本课程紧紧围绕医学人工智能、机器学习、智能机器人等前沿技术，通过医工交叉理论知识、智能诊断模型训练、医学机器人展开学习体验，激发人工智能在口腔领域应用的研发创新思维，体现新医科以人工智能、大数据科技革命为基础的面向精准医学、转化医学和智能医学的人才培养要求。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
