WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('口腔医学院', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '口腔外科学（下）', dept.dep_id, '口腔颌面外科学是一门以外科治疗为主，研究口腔器官（牙、牙槽骨、唇、颊、舌、腭、咽等）、面部软组织、颌面诸骨（上颌骨、下颌骨、颧骨等）、颞下颌关节、唾液腺以及颈部某些疾病防治为主要内容的学科。口腔颌面外科学作为口腔医学的重要组成，需要掌握的基本内容包括口腔颌面部的检查和局部麻醉、牙及牙槽外科、修复前外科、颞下颌关节病、颌面部损伤、唾液腺疾病、颌面部神经疾患、口腔颌面部感染疾病，还应掌握颌面部畸形、牙颌面畸形等口腔颌面部整形外科的治疗及操作技能等内容。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

