  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '出土文献选读(H)', dept.dep_id, '自20世纪以来，出土文献的发现与研究蔚成风潮，王国维提倡的二重证据法，主张以“地下之新材料”与“纸上之材料”互证，被学者视为中国现代史学成立的标志。二十世纪中国学术史的四大发现，殷墟甲骨、西域简牍、敦煌文书、内阁档案，前三者皆属于出土文献的范围。最近二十年来，围绕先秦秦汉简牍、敦煌吐鲁番文书、北朝隋唐石刻这三类出土文献的研究工作成为唐以前历史研究中的核心议题，产生丰硕的学术成果。可以说能否利用出土文献展开学术工作已成为学者是否“预流”的重要尺度，同时也是学生学术能力培养中的必要环節。

本课程主要包含简牍、文书、石刻这三类目前学术界最关注的出土文献形态（每次开课讲授两个模块），通过典型研究示例、重要文献释读和各类专题讨论，使学生得到综合性的学术训练，掌握出土文献研究的基础技能与基本方法，提高学生研读历史文献和运用新史料研究新问题的能力，引导学生探索有待开拓的新领域。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

