  VALUES ('旅游学系', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '管理心理学（MTA）', dept.dep_id, '本课程旨在引导学生系统理解组织环境中个体、群体、领导及组织整体的心理与行为规律，掌握管理心理学的基本概念与研究方法。通过理论讲解与实践案例分析，培养学生运用心理学原理分析与解决组织管理实际问题的能力，为其未来从事相关专业工作奠定坚实的知识与能力基础。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

WITH dept AS (
  SELECT dep_id FROM Department WHERE dep_name = '旅游学系'
), course_row AS (
  SELECT c.course_id
  FROM Course c
  JOIN dept d ON d.dep_id = c.dep_id
  WHERE c.course_name = '管理心理学（MTA）'
), existing_teacher AS (
  SELECT t.people_id
  FROM Teacher t
  JOIN People p ON p.people_id = t.people_id
  JOIN dept d ON d.dep_id = t.dept_id
  WHERE p.name = '施媛媛'
  ORDER BY t.people_id
  LIMIT 1
), inserted_person AS (
  INSERT INTO People (name, gender, phone, email)
  SELECT '施媛媛', 'O', NULL, NULL
  WHERE NOT EXISTS (SELECT 1 FROM existing_teacher)
  RETURNING people_id
), person_row AS (
  SELECT people_id FROM existing_teacher
  UNION ALL
  SELECT people_id FROM inserted_person
  LIMIT 1
), teacher_row AS (
  INSERT INTO Teacher (people_id, staff_no, title, dept_id)
  SELECT person_row.people_id,
         'CR14C2047604',
         '其他',
         dept.dep_id
  FROM person_row, dept
  ON CONFLICT (people_id)
  DO UPDATE SET dept_id = EXCLUDED.dept_id
  RETURNING people_id
)
INSERT INTO Teaching (teacher_id, course_id, semester)
SELECT teacher_row.people_id, course_row.course_id, '2025-2026-2'
FROM teacher_row, course_row
ON CONFLICT (teacher_id, course_id, semester) DO NOTHING;

WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('旅游学系', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '国际旅游服务贸易：实务与前沿', dept.dep_id, '国际旅游服务贸易是国际服务贸易的一种，也是全球服务业中发展最快的产业之一，在国际服务贸易领域中有重要的地位。近几年，随着我国国际地位不断提升，我国旅游服务贸易规模不断扩大，尤其以出入境旅游为例，全球市场繁荣态势显著。国际旅游服务贸易不仅促进了我国与其他国家（地区）之间的商品贸易、资本流动、信息交流和人员往来，而且带动了中国文化走向世界，对塑造国家形象、提升我国的国际地位和国际形象具有重要的作用。

本课程内容覆盖旅游服务贸易的理论、政策、规则、发展趋势和变化特点、产业基础等内容，旨在培养学生成为具有国际服务贸易领域专业知识与技能的高层次人才。通过课程学习，学生可以更加深入了解和学习关于国际旅游服务贸易的相关理论与专业知识，掌握国际旅游服务贸易的最新发展动态以及最新的统计数据，了解国际旅游服务贸易领域学术前沿研究专题。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
