  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '当代俄罗斯马克思主义研究', dept.dep_id, '《当代俄罗斯马克思主义研究》课程是面向马克思主义理论相关专业学生，系统探究 21 世纪俄罗斯马克思主义发展脉络、理论格局与实践价值的重要教学载体，也是深化马克思主义国别化研究、拓宽马克思主义理论国际视野的重要思政教育渠道。本课程立足全球化与资本主义频发危机的时代背景，以 21 世纪俄罗斯马克思主义的复兴与发展为核心主线，结合苏联解体后俄罗斯的社会现实与历史抉择，系统阐释当代俄罗斯马克思主义的复兴动因、学术格局、理论成果，深入剖析其面临的现实困境与发展前景，重点解读其对构建 21 世纪世界马克思主义、推进马克思主义中国化时代化的特殊意义。通过本课程的学习，学生能从整体上把握当代俄罗斯马克思主义的基本理论与发展规律，明晰马克思主义俄国化的历史脉络与 21 世纪新发展，深化对马克思主义国别化发展逻辑的理解；能准确辨析俄罗斯马克思主义五大研究派别的理论主张与核心特征，把握其对当代资本主义的批判视角与研究方法；能立足中俄马克思主义发展的比较视域，明晰苏联马克思主义的经验教训，深刻认识马克思主义中国化时代化的理论优势与实践价值，进而提升分析国外马克思主义发展问题的理论素养与思辨能力，坚定马克思主义中国化时代化的理论自信，培养推动 21 世纪世界马克思主义发展的国际视野与责任意识。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
