WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('脑科学转化研究院', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '神经科学交叉与转化', dept.dep_id, '本课程将概述神经交叉学科的进展与转化，着重讲授神经环路的功能和调控机制，脑发育的可塑性，神经内分泌与免疫系统之间的相互作用，干细胞与神经再生，躯体感觉信息的处理与感觉系统的分子细胞机制，神经系统疾病的基础研究和临床转化，脑肿瘤的转化研究，以及现代神经系统研究方法技术。 通过本课程的学习，要求学生能够充分了解神经交叉学科的研究概况，掌握神经交叉学科常用的研究方法，学会运用科学的思维和科学研究方法分析问题、解决问题，并掌握查阅文献、综合分析问题的方法与技能。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

