  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT 'AI辅助的神经生物学前沿分析方法', dept.dep_id, '本课程聚焦人工智能与神经科学交叉领域前沿，面向具有神经科学或医学背景的师生，系统构建AI技术在脑科学研究和临床转化中的创新应用知识体系。课程采用"理论奠基-技术解析-案例研讨"的三维教学模式，通过建立动态演进的学科交叉实践平台，培养精通实验与AI学科语言的具有原创能力的神经生物科研人才。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

