WITH dept AS (
  SELECT dep_id FROM Department WHERE dep_name = '社会发展与公共政策学院'
), course_row AS (
  SELECT c.course_id
  FROM Course c
  JOIN dept d ON d.dep_id = c.dep_id
  WHERE c.course_name = '文化与健康'
), existing_teacher AS (
  SELECT t.people_id
  FROM Teacher t
  JOIN People p ON p.people_id = t.people_id
  JOIN dept d ON d.dep_id = t.dept_id
