  VALUES ('社会发展与公共政策学院', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '质性研究方法', dept.dep_id, '以社会学和人类学田野研究案例为基点，本课程力求使学生对社会科学定性研究方法对于观察、描述和分析不同历史条件和特定语境中的社会事实和文化过程的意义和局限，有所领悟、体验和反思。教学将采取课堂讲授、专题讨论和田野实践相结合的方式，使修课学生领会到定性研究在实地考察、数据的收集整理和分析以及学术论文撰写过程中的关键作用，对“定性” 研究方法背后所蕴含的理论脉络有清晰的了解，从而加深对社会和人文科学学科这一主要研究手段的认识和体会。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

WITH dept AS (
  SELECT dep_id FROM Department WHERE dep_name = '社会发展与公共政策学院'
), course_row AS (
  SELECT c.course_id
  FROM Course c
  JOIN dept d ON d.dep_id = c.dep_id
  WHERE c.course_name = '质性研究方法'
), existing_teacher AS (
  SELECT t.people_id
  FROM Teacher t
  JOIN People p ON p.people_id = t.people_id
  JOIN dept d ON d.dep_id = t.dept_id
  WHERE p.name = '张聪'
  ORDER BY t.people_id
  LIMIT 1
), inserted_person AS (
  INSERT INTO People (name, gender, phone, email)
  SELECT '张聪', 'O', NULL, NULL
  WHERE NOT EXISTS (SELECT 1 FROM existing_teacher)
  RETURNING people_id
), person_row AS (
  SELECT people_id FROM existing_teacher
  UNION ALL
  SELECT people_id FROM inserted_person
  LIMIT 1
), teacher_row AS (
  INSERT INTO Teacher (people_id, staff_no, title, dept_id)
  SELECT person_row.people_id,
         'CR729AB4871B',
         '其他',
         dept.dep_id
  FROM person_row, dept
  ON CONFLICT (people_id)
  DO UPDATE SET dept_id = EXCLUDED.dept_id
  RETURNING people_id
)
INSERT INTO Teaching (teacher_id, course_id, semester)
SELECT teacher_row.people_id, course_row.course_id, '2025-2026-2'
FROM teacher_row, course_row
ON CONFLICT (teacher_id, course_id, semester) DO NOTHING;

WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('社会发展与公共政策学院', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '智力心理学', dept.dep_id, '本课程围绕“智力（intelligence）”这一核心心理学构念，采用“经典理论 → 前沿交叉 → 社会应用”的递进结构，系统讲授智力的心理测量学基础与关键争议，并强化三条前沿主线：认知神经科学证据、跨文化智力比较与测评公平、以及人工智能与人类智力的关系。

课程在保留经典心理测量框架（如一般智力g、层级模型、信度与效度、测验标准化等）的同时，引导学生把这些框架迁移到真实世界的评估问题中（教育与选拔、健康老化与临床特殊人群、以及AI时代的评估与治理）。

课程采用项目式学习（PBL）与结构化同伴评审，培养学生在跨文化与AI情境下进行“可测量、可解释、可公平”评估方案设计与批判性论证的能力。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

WITH dept AS (
  SELECT dep_id FROM Department WHERE dep_name = '社会发展与公共政策学院'
), course_row AS (
