WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('生命科学学院', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '细胞器生物学', dept.dep_id, '围绕细胞器展开的研究是细胞生物学领域的重要分支。近些年来随着技术突飞猛进，细胞器生物学领域的进展很多，对生物学其它领域的借鉴意义很大。线粒体、过氧化物酶体在专业必修课《细胞生物学》的授课中没有大量展开，而其功能异常导致了多种人类疾病，是重要的科学研究对象。脂滴源自内质网，有单层磷脂的膜（与线粒体双层生物膜、过氧化物酶体单层生物膜形成对比），亦与人类疾病密切相关。通过深入讲解膜性细胞器的结构、功能，串联专业必修课已经涉及的有关膜、细胞骨架、能量和代谢的内容，突出学科知识的彼此交织，促进学生对书本知识的融会贯通。新技术和新分析方法的采用，也推动了细胞器相互作用的机制研究；相关的教学内容有助于开阔学生的视野，使学生能够整体地来看发生在细胞内的诸多生物学过程。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

