WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('外国语言文学学院', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '阿拉伯伊斯兰文化', dept.dep_id, '阿拉伯伊斯兰文化是人类文明体系中持续发展的重要组成部分之一，作为世界四大未断代文化传统之一，它在历史长河中形成了独特的宗教信仰、语言体系、艺术表达、哲学思想与社会制度。本课程旨在通过系统的学术探究，引导学生深入理解阿拉伯伊斯兰文化的形成、演变及其对全球文明的影响。

本课程以历史发展为主线，依循 起源、发展、转型、现代化与全球化 的脉络，探讨阿拉伯伊斯兰文化的内在结构、变迁动力及跨文化互动。课程内容涵盖伊斯兰教兴起前的阿拉伯文化、伊斯兰文明的建立与鼎盛、殖民主义影响下的文化变革、现代民族国家的形成，以及当代阿拉伯文化在全球化进程中的角色。通过对历史文献、学术研究、多语种（阿拉伯语、英语、法语、中文）文本、影音资料的分析，学生将掌握研究阿拉伯伊斯兰文化的多重途径，拓展对世界文明体系的整体认知。

此外，课程将结合 东方学理论、跨文化研究、全球化视角 ，深入探讨阿拉伯世界与西方社会的关系，特别是法国、英国等前殖民国家对阿拉伯世界的影响，以及当代中阿关系在“一带一路”框架下的文化、经济与政治互动。通过跨学科的方法论训练，学生将能够批判性地分析阿拉伯伊斯兰文化的复杂性，理解其在历史与现代性之间的张力，并培养全球化时代下的文化理解与比较研究能力。

本课程适合对中东历史、伊斯兰文明感兴趣的学生，亦可为国际关系、历史学、人类学、宗教学等相关专业提供跨学科视角。课程强调学术研究与现实关照的结合，鼓励学生在课堂讨论、小组研究、案例分析等实践性教学环节中积极探索阿拉伯伊斯兰文化的多维特性。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

