  VALUES ('外国语言文学学院', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '高级韩国语(下)', dept.dep_id, '本课程系外文学院韩国语专业基础课，适合该专业三年级学生修读。培养学生外语思维能力和使用能力，使学生达到能够熟练而正确地运用所学知识进行表达和交流。掌握高级阶段词汇及语法，促进语法知识转换为实际语言能力。主要讲授有代表性的韩国作品。主要涉及韩国社会、文化与生活的各个方面以及人们所关心的社会问题。对作品的思想内容，篇章结构、文体修辞和语言风格进行分析，以提高学生对韩国文学，经济，文化等方面的理解、分析及评述的能力，达到能够熟练而正确地运用所学知识，形象而具体地表达和交流，进一步提高语言运用能力。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

WITH dept AS (
  SELECT dep_id FROM Department WHERE dep_name = '外国语言文学学院'
), course_row AS (
  SELECT c.course_id
  FROM Course c
  JOIN dept d ON d.dep_id = c.dep_id
  WHERE c.course_name = '高级韩国语(下)'
), existing_teacher AS (
  SELECT t.people_id
  FROM Teacher t
  JOIN People p ON p.people_id = t.people_id
  JOIN dept d ON d.dep_id = t.dept_id
  WHERE p.name = 'Seong Gowoon'
  ORDER BY t.people_id
  LIMIT 1
), inserted_person AS (
  INSERT INTO People (name, gender, phone, email)
  SELECT 'Seong Gowoon', 'O', NULL, NULL
  WHERE NOT EXISTS (SELECT 1 FROM existing_teacher)
  RETURNING people_id
), person_row AS (
  SELECT people_id FROM existing_teacher
  UNION ALL
  SELECT people_id FROM inserted_person
  LIMIT 1
), teacher_row AS (
  INSERT INTO Teacher (people_id, staff_no, title, dept_id)
  SELECT person_row.people_id,
         'CREEAAEB5C30',
         '其他',
         dept.dep_id
  FROM person_row, dept
  ON CONFLICT (people_id)
  DO UPDATE SET dept_id = EXCLUDED.dept_id
  RETURNING people_id
)
INSERT INTO Teaching (teacher_id, course_id, semester)
SELECT teacher_row.people_id, course_row.course_id, '2025-2026-2'
FROM teacher_row, course_row
ON CONFLICT (teacher_id, course_id, semester) DO NOTHING;

