  VALUES ('外国语言文学学院', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '基础口译', dept.dep_id, '本课程是翻译硕士（MTI）口译方向的核心必修课程，旨在系统性地培养学生的交替传译核心能力。课程植根于口译理论与实践相结合的原则，通过科学、循序渐进的训练，使学生掌握包括听辨理解、信息记忆、口译笔记及双语表达在内的全套交传技能。教学内容紧密对接国家国际传播战略与上海市作为国际大都市的发展需求，覆盖外交、经贸、金融、法律、航运、科技等高端涉外领域。

课程最大特色在于其 “实战化” 与 “战略性” 。大量采用授课教师在一线国际会议（如上海论坛、进博会等）中的真实口译素材作为教学案例，确保教学内容的时效性与专业性。同时，课程以 “服务学习” 和 “以赛促教” 为两大导向，积极组织学生参与高级别口译竞赛和真实涉外活动口译实践，全面锻造学生的专业素养、职业精神与国际视野，为培养国家急需的高端口译与国际传播人才奠定坚实基础。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

