WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('外国语言文学学院', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '交替传译 （下）', dept.dep_id, 'MTI口译方向的高阶核心课程，面向已具备基础交替传译技能的大三学生，重点提升其在真实语境中进行高强度、中高专业难度交传任务的能力。课程内容紧密结合时代主题与社会热点，覆盖科技、经贸、外交、能源、环境、教育、企业发展等多个领域，设置系统化、模块化的主题训练任务。

课程选用大量源自真实国际会议、新闻发布会、人物访谈与政策通道的语料，强调双向训练（英译中、中译英）并重，突出信息提取、笔记整合、语言重构、术语处理、表达策略、语体适应等实用技能。训练任务包括：部长通道讲话、人工智能与5G演讲、国际会议开幕辞、经济发展趋势分析、职业伦理讨论、模拟新闻发布、城市推介模拟会议、“中国故事”叙事等。

在教学方式上，课程采用“案例分析 + 分组演练 + 模拟会议 + 教师点评 + 自我反思”相结合的多元模式，配合系统化的技能梯度设计与模拟实战环境构建，帮助学生逐步实现从“能译”到“善译”的跨越。最终目标是使学生具备胜任国际交流、媒体沟通、政务发布等多种高要求口译场景的能力，并在翻译实践中体现专业精神、人文素养与国家叙事能力。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

