WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('外国语言文学学院', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '强国之路：形势、政策与使命Ⅳ', dept.dep_id, '“强国之路”思政大课“悟”阶段交叉讨论课是在“学—思—践”学习基础上的深化环节，旨在引导学生从实践经验走向理论反思，从项目实践走向研究问题凝练，是连接实践探索与学术研究的重要过渡阶段。

课程以学生在“践”阶段完成的小组课题为基础，通过组织跨学科交叉讨论，引导学生在交流与互评中深化对现实问题与国家发展议题的理解。课程围绕“立问—立意—立论”的学习逻辑，通过三次交叉讨论课，引导学生系统梳理课题背景、研究问题与实践路径，并在跨学科对话中进一步凝练研究问题、拓展研究视角。

在课程过程中，学生通过课题展示、跨组提问、同行评议和教师点评等多种方式参与讨论，在多学科交流中形成更加开放的知识结构和问题意识。课程不仅强调研究能力与表达能力的培养，也强调学生将专业学习与国家发展需求相结合，在思考具体问题的过程中进一步理解“我为强国建设能做什么、如何做”的时代命题。

通过本课程学习，学生能够在实践经验基础上形成更具深度的研究思考，为后续独立研究报告撰写以及进一步科研探索奠定基础。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

