  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '中级德语（下）', dept.dep_id, '本课程以《当代大学德语4》为核心教材，旨在帮助学生完成从中级到高级德语水平的跨越。通过深度解析复杂语法与专业词汇，全面提升学生在学术及日常生活中的跨文化沟通能力。本课程打破传统听读教学，强调“思辨与表达”：具体模块包括：

