  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '世界遗产概论', dept.dep_id, '本课程以联合国教科文组织（UNESCO）世界遗产体系为核心，系统讲授其历史缘起、制度框架与全球实践。课程内容涵盖世界遗产公约的宗旨与演变、申报评审机制、主要遗产类型及其识别标准，并深入分析全球范围内遗产保护的实践贡献与现实挑战。

课程将重点关注若干前沿与跨学科议题，包括但不限于“世界遗产与生物多样性保护”、“可持续旅游与遗产管理”、“气候变化对遗产的影响”、“原住民与社区参与”、“世界遗产教育”等专题，引导学生理解遗产保护在当代社会中所承载的多重价值与复杂语境。

作为课程重要组成部分，本专题将系统梳理中国世界遗产的申报历程、管理经验及其国际贡献，并深入探讨国际保护理念与中国实践之间的互动，从而反思世界遗产体系对完善中国本土自然与文化遗产保护制度的启示与推动。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

