WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('物理学系', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '近代物理实验I', dept.dep_id, '这是一门为物理系高年级学生开设的必修课。它挑选了那些在物理学发展史上起过重大作用或获得诺贝尔物理奖的实验作为主要教学内容，并采用“模拟科研实验”的方式进行教学。鼓励学生的创新意识，注重培养学生在实验物理方面的能力，如选题、设计及组建实验系统，使学生从实验技术型向实验研究型方向转变。

近代物理实验目前有23个（44套）实验，这些实验包括历史上曾获得诺贝尔奖的研究物理现象的研究型实验以及反映当前新科学技术的应用型物理实验，涉及光学、电子物理、固体物理、原子核物理、低温超导等学科领域。

近代物理实验室从1950年代（当时称中级物理实验室）建立至今已有七十多年，它为培养人才作出很大努力与贡献。实验室已建立了一套有效的教学方法及管理制度，为培养优秀人才提供了比较好的基础条件。特别是最近几年在教材、教学内容、教学方法上进行教学改革实践，使物理实验的水平上了一个台阶。有不少实验走在国内同行的前列。学生通过实验把理论与实践结合起来，用实验手段研究物理现象，加深对理论知识的理解，在实验能力，对物理现象的思维、分析、判断、综合能力等各方面都得到较好的训练。通过近代物理实验课以及其它有关课程的学习，学生能成为具有一定的物理头脑、了解新科学知识、掌握计算机技术的新型人才。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

