  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '理论原子核物理', dept.dep_id, '本课程是面向理论物理及核科学专业研究生的核心专业课，旨在构建系统的原子核多体量子理论框架。课程内容涵盖从唯象模型到微观理论的演进：首先确立必要的数学形式，深入剖析核壳层模型与原子核集体模型，并详细阐释Hartree-Fock 平均场方法及核多体理论的核心思想。在此基础上，课程将从静态结构转向动力学过程，系统论述电磁跃迁、弱相互作用及核散射理论，并探讨共振、聚变、裂变与重离子碰撞等复杂反应机制的微观图景。最后，课程将视野拓展至亚原子物理与核天体物理，引导学生建立从核子自由度到天体演化过程的跨尺度物理图像。通过本课程，学生将掌握处理复杂量子多体系统的理论工具，为从事核物理及相关前沿领域的科研工作奠定坚实基础。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
