WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('新闻学院', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '智能媒介概论', dept.dep_id, '本课程共分为三部分：绪论（历史、理论）、智能媒介实践、业界调研。

一、“绪论” ，包括历史和理论两讲。历史部分探讨人工智能媒介的技术史、思想史、社会史、文化史；理论部分旨在让学生掌握理解人工智能基本特征和运行方式的核心概念，以及智能媒介的基本含义及社会影响。探讨当下人文社会科学关于人工智能的核心议题。

二、“智能媒介实践”板块 ，围绕5个专题，以理论学习加案例分析的形式，帮助学生在人工智能应用涌现的时代语境中把握智能媒介产生的现实场景及运作机制，包括： 专题 一 ：智能新闻 。围绕中外新闻业的AI实践和有关AI与新闻的学术研究，探究人工智能对新闻（news）、新闻工作者（journalists）和新闻业（journalism）的影响。 专题 二 ：智能游戏 。探究游戏作为普通用户与人工智能最初相遇的媒介，如何连接、转变、生成新的智能沟通关系，从而创造新的社会运作方式，建构新的文明。 专题 三 ：数字与智能记忆 。将结合记忆研究的哲学、社会学和心理学传统，探讨一系列理论、实践和伦理议题，包括：数字记忆的元话语与社会技术想象；遗忘终结与个体记忆的变迁；记忆的外置及其工业化；假肢记忆；数字遗产与逝者“复活”；数字-AI记忆伦理和政治。 专题 四 ：智能城市 。探究人工智能如何激活不同场景的媒介系统，改变人、商品、信息的流动交汇，重构城市公共生活。 专题 五 ：智能治理 。介绍智能治理的特点和基本内涵，阐述其与传统治理模式的差异，并结合智能技术在政府治理和互联网平台治理这两个不同领域的应用和最新发展，探讨人工智能技术的深远影响。

三、“业界调研”板块 ，理论与实践并重，与实际的多元化的人工智能项目建立联系，基于大量、丰富的人工智能媒介实践观察，引导学生关注中国人工智能发展的本土化经验，及时追踪人工智能最新技术前沿。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

