WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('药学院', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '生物技术药物给药系统', dept.dep_id, '生物技术的迅猛发展促进了生物技术药物的大量生产。生物技术药物（又称生物药，Biological Drugs or Biologics）是指以细胞及其组成分子为原始材料，利用生物系统、活生物或其衍生物生产出来的用于预防、治疗和诊断的生物活性物质，包括多肽、蛋白质、酶、核酸和细胞生长因子等类药品。该类药品因生产技术上的特殊性使其与传统意义上的一般化学药品有着许多不同之处。

生物技术药物给药系统是指肽类、蛋白质和核酸等药物以一定的给药形式经一定的给药途径较为精确地应用于人体的技术系统，亦即药物从制剂制备到临床应用整个过程的研制体系。以蛋白肽类药物为主的生物技术药物在结构、功能和作用上与其他药物的不同决定了它们在临床使用中的复杂性和困难性，单一的注射剂远远不能满足日益增长的生物技术药物的临床应用需求。因此，研究开发生物技术药物给药技术与给药系统并制备成高质量的新制剂既是现代药剂学面临的重大而艰巨的任务，也是现代药剂学研究的一个热点领域。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

