  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '体内药物与毒物分析', dept.dep_id, '《体内药物与毒物分析》是从药物分析派生出的新兴学科，是一门运用药物分析的原理和技术，对生物机体中药物及其代谢物、内源性物质以及侵入生物体内的有毒物质进行定性和定量分析，为临床药学、临床药理学、生物药剂学，以及法医学提供技术支持的一门综合性较强的应用学科。体内药物与毒物分析是一门研究生物机体内药物及其代谢物和内源性物质的质与量变化规律的分析方法学。毒物分析是应用化学、药学、医学等学科的现代科学理论、技术和方法，对危害人类健康生存的化学物质进行分析研究的一门应用学科。体内药物分析直接关系到药物的研发及临床应用，药物作用机制的探讨、成药性的评价及药物临床应用的指导等各阶段的工作。体内毒物分析主要是对涉及或怀疑涉及由毒物引起的伤害或死亡事件中的有关物质进行分析鉴定。两者均属于微量分析或痕量分析。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

