WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('哲学学院', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '悲剧与哲学', dept.dep_id, 'PHIL30143.01 悲剧与哲学 Tragedy and Philosophy
悲剧与哲学Tragedy and Philosophy

本课程为悲剧与哲学，旨在考察古希腊以降至现代性悲剧和哲学的张力和共生。课程将分析公元前五世纪柏拉图哲学和同期悲剧作品的历史背景和成因 (柏拉图、亚里士多德、埃斯库罗斯、索福克勒斯、欧里庇得斯)，并追溯其在德国古典哲学(黑格尔、谢林)、 浪漫派(荷尔德林)和十九、二十世纪(尼采、海德格尔、本雅明)哲学和美学思想中的复兴和再阐释，带领学生阅读相关哲学和悲剧作品节选、适当熟悉当代学界对类似问题的重新讨论，剖析哲学和悲剧作为一种思想方式和存在方式的历史可能性。课程将鼓励学生追问、深入思考什么是哲学、悲剧如何作为他者重构哲学、哲学又如何回答悲剧提出的有关苦难、存在意义、家国、个人、性别、公正等根本问题。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

