WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('智能机器人与先进制造创新学院', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '飞行力学与飞行控制', dept.dep_id, '飞行力学与飞行控制是飞行器设计与工程专业的专业基础课。本课程以有人驾驶固定翼飞机为研究对象，建立其六自由度非线性运动方程，在此基础上首先研究飞机质心的运动规律，并讲授飞机的基本飞行性能、续航性能、机动性能、起降性能等的计算方法。然后利用线化理论研究飞机的稳定性和操纵性——着重分析存在外界扰动或操纵作用下飞机的运动特性，包括如何实现各种平衡飞行、平衡飞行状态受外界扰动后所呈现的运动稳定性及飞机对于操纵的响应等。最后简要介绍现代智能飞行控制系统的基本原理和方法。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

