WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('中国语言文学系', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '中国古代文体学研究', dept.dep_id, '汉字是单音节词，故骈偶化是书面语言对口语的修饰的基本方式。早期的书面语多有骈偶化特点。东汉后，经六朝世族社会积累，骈偶文取代了散体文的文正宗地位，成为书面语的唯一正宗形式。完成脱离了口语，这一现象在南朝尤盛，亦产生种弊端，改革之风时起。改革者以散体为古文，以骈偶文为时文，骈散之别也成为古今之争，涉及内容有三：1，南北文化问题：骈盛于南，古散多存于北，语体之别是隋唐文化对立的一种形态，文体磨合也是南北文化汇融的一种方式；2，文化观念问题：儒经以散体为主，倡古文散体者，强调师法儒家经籍，重传承儒学精神；学时文者以《文选》等南朝文为教材，重叙个人才情。倡古文多与复古道，振儒学相联系，多能取得意识形态的制高点。3，世庶文化问题；骈偶文的繁细化，完全脱离口语，成为非专门学习则不可掌握的特殊语言，在贵族社会里，接受书面训练是贵族特权之一，这种书面语言也成为贵族身份标志，也成为传情达志的障碍，势必为接近口语散体文取代。但也是吸取骈文语言艺术基础上形成的合古今骈散于一体新型书面语。韩柳是较早且较成功的探索者，从不同方面为此后书面语指明的方向，树立了范式。因此，探索韩柳文最初的努力与用心，可对中古近世书面汉语表达方式与功能有更深入的认识。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

