WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('中国语言文学系', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '中西文艺学名著导读', dept.dep_id, '本课程对中文系本科与研究生中对文艺学美学有深入学习要求的学生开设。主要选择西方20世纪上半叶最主要的文学实践和思潮：存在主义的文学理论著述进行学习；同时存在主义对中国现当代文学也产生了深远的影响，本课程也对中国现当代有关存在主义的文学理论论述进行选读。存在主义对世纪转折以及两次世界大战期间，西方的思想与文化的“危机”进行了深刻的反思，探寻人类生存的新的方向，提出了理解世界、人生的整套的理论，并且形成了很有规模声势的文学运动，产生了大量作品。这个理论，既有深刻的存在哲学作为根据和基础，也有对于具体日常生存情绪与处境的细腻深刻的体会与厘定，对于一般文学感悟和理解具有较好的参考作用。课程对于存在主义思潮的介绍，分为广角和专题两个方面，一方面从面上介绍存在主义的分布情况，另一方面介绍存在主义主要理论家尼采、海德格尔、萨特、加缪等人的文论思想。通过课堂讲述与课外阅读，了解存在主义的基本状况，把握主要理论家的主要思想，加深对于存在主义文学作品的体会与理解，同时也训练一般文论读解和应用能力。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

