WITH dept AS (
  INSERT INTO Department (dep_name, description)
  VALUES ('中山临床医学院', '由复旦教学大纲抓取脚本自动补充。')
  ON CONFLICT (dep_name)
  DO UPDATE SET description = COALESCE(Department.description, EXCLUDED.description)
  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '循证医学', dept.dep_id, '循证医学核心思想是医务人员应该认真地、明智地、深思熟虑地运用在临床研究得到的最新、最有利的科学研究信息来诊治病人。它是一种理念，将最佳证据、医生的临床经验以及病人的需求和价值观三者结合起来。实践循证医学的步骤包括提出问题、检索证据、评价证据、应用证据和效果评价。主要教学内容分为10个单元：(1)绪论;(2)临床证据资料及检索方法;(3)疾病诊断证据的分析评价;(4)疾病治疗证据的分析评价;(5) 病因及危险因素的分析评价; (6)疾病预后证据的分析评价; (7) 生命质量的分析评价;(8) 药物不良反应的分析评价;(9) 系统综述与Meta分析; (10)临床实践指南。

在教学中，将循证医学的学科特点与科学方法论、医患共决策、学科发展趋势结合起来，围绕科学思辨与人文关怀这一思政主题，提高学生自主学习能力，培养医学生循证医学临床应用能力，形成“以病人为中心”的职业素养和“基于证据决策”的学术修养，最终提高临床医学岗位胜任力的核心能力。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

