  RETURNING dep_id
), course_row AS (
  INSERT INTO Course (course_name, dep_id, description)
  SELECT '诊断学C', dept.dep_id, '《诊断学C》总课程为4个月，共32个学时，基本内容包括：呼吸、循环、消化、神经系统疾病症状，全身体格检查，基本实验室检查（血液一般检查、贫血检查、肾功能、尿常规和尿液其他检查、肝脏病常用实验室检查）、心电图。作为学生基础课程与临床学习阶段的桥梁有着举足轻重的作用，知识点的传输，临床实践的运用显得尤为重要突出。难点也就在如何更好的让学生接受患者，感受临床；可以通过多媒体教学、模拟患者、情景教学让学生加深印象。'
  FROM dept
  ON CONFLICT (course_name, dep_id)
  DO UPDATE SET description = EXCLUDED.description
  RETURNING course_id, dep_id
)
SELECT course_id FROM course_row;

